     1→/* ==========================================================================
     2→   Base Design System - Protocodus
     3→   ========================================================================== */
     4→:root {
     5→  /* Colors based on Logo */
     6→  --clr-bg: #FAFAFA;
     7→  --clr-text: #1A1A1A;
     8→  --clr-yellow: #FFC400;
     9→  --clr-mint: #00FFC3;
    10→  --clr-black: #1A1A1A;
    11→  --clr-white: #FFFFFF;
    12→  --clr-grey: #888888;
    13→  --clr-text-muted: #555555;
    14→
    15→  /* Typography */
    16→  --font-primary: 'Space Grotesk', sans-serif;
    17→
    18→  /* Typography Scale (1.2x ratio) */
    19→  --fs-xs: 0.75rem;
    20→  --fs-sm: 0.85rem;
    21→  --fs-base: 1rem;
    22→  --fs-md: 1.2rem;
    23→  --fs-lg: 1.45rem;
    24→  --fs-xl: 1.75rem;
    25→  --fs-2xl: 2.1rem;
    26→  --fs-3xl: 2.5rem;
    27→  --fs-4xl: 3rem;
    28→  --fs-5xl: 3.6rem;
    29→  --fs-6xl: 4.3rem;
    30→  --fs-7xl: 5.2rem;
    31→
    32→  /* Line Heights */
    33→  --lh-tight: 1.2;
    34→  --lh-snug: 1.5;
    35→  --lh-normal: 1.7;
    36→  --lh-relaxed: 1.8;
    37→
    38→  /* Letter Spacing */
    39→  --ls-tight: -0.02em;
    40→  --ls-normal: 0;
    41→  --ls-wide: 1px;
    42→  --ls-wider: 2px;
    43→
    44→  /* Layout & Spacing (8px base) */
    45→  --container-width: 1120px;
    46→  --space-xs: 0.5rem;
    47→  --space-sm: 1rem;
    48→  --space-md: 1.5rem;
    49→  --space-lg: 2rem;
    50→  --space-xl: 3rem;
    51→  --space-2xl: 4rem;
    52→  --space-3xl: 5rem;
    53→  --space-4xl: 7rem;
    54→
    55→  /* Aesthetics */
    56→  --border-radius: 0px;
    57→  --border-radius-pill: 999px;
    58→  --border-width: 2.5px;
    59→  --shadow-sm: 1px 1px 0px var(--clr-black);
    60→  --shadow-md: 2px 2px 0px var(--clr-black);
    61→  --shadow-lg: 4px 4px 0px var(--clr-black);
    62→  --shadow-xl: 6px 6px 0px var(--clr-black);
    63→  --shadow-solid: 4px 4px 0px var(--clr-black);
    64→  --shadow-solid-hover: 1px 1px 0px var(--clr-black);
    65→  --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    66→
    67→  /* Focus State */
    68→  --focus-outline: 2px solid var(--clr-yellow);
    69→  --focus-outline-mint: 2px solid var(--clr-mint);
    70→}
    71→
    72→/* Base Reset */
    73→*,
    74→*::before,
    75→*::after {
    76→  box-sizing: border-box;
    77→  margin: 0;
    78→  padding: 0;
    79→}
    80→
    81→html {
    82→  scroll-behavior: smooth;
    83→  -webkit-font-smoothing: antialiased;
    84→  -moz-osx-font-smoothing: grayscale;
    85→}
    86→
    87→body {
    88→  font-family: var(--font-primary);
    89→  color: var(--clr-text);
    90→  line-height: var(--lh-normal);
    91→  overflow-x: hidden;
    92→  font-size: var(--fs-base);
    93→}
    94→
    95→/* Animated Background (p5.js) */
    96→.bg-animation-container {
    97→  position: fixed;
    98→  top: 0;
    99→  left: 0;
   100→  width: 100vw;
   101→  height: 100vh;
   102→  z-index: -1;
   103→  overflow: hidden;
   104→  pointer-events: none;
   105→  background-color: var(--clr-bg);
   106→}
   107→
   108→.bg-animation-container canvas {
   109→  display: block;
   110→  width: 100% !important;
   111→  height: 100% !important;
   112→}
   113→
   114→/* Skip to content link */
   115→.skip-link {
   116→  position: absolute;
   117→  top: -40px;
   118→  left: 0;
   119→  background-color: var(--clr-black);
   120→  color: var(--clr-white);
   121→  padding: 0.75rem 1rem;
   122→  text-decoration: none;
   123→  z-index: 9999;
   124→  font-weight: 700;
   125→}
   126→
   127→.skip-link:focus {
   128→  top: 0;
   129→}
   130→
   131→a {
   132→  text-decoration: none;
   133→  color: inherit;
   134→}
   135→
   136→ul {
   137→  list-style: none;
   138→}
   139→
   140→img,
   141→svg {
   142→  max-width: 100%;
   143→  display: block;
   144→}
   145→
   146→.container {
   147→  max-width: var(--container-width);
   148→  margin: 0 auto;
   149→  padding: 0 var(--space-lg);
   150→}
   151→
   152→.section {
   153→  padding: var(--space-3xl) 0;
   154→}
   155→
   156→/* ==========================================================================
   157→   Scroll Reveal Animation
   158→   ========================================================================== */
   159→.reveal {
   160→  opacity: 0;
   161→  transform: translateY(40px);
   162→  transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1),
   163→    transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
   164→}
   165→
   166→.reveal.visible {
   167→  opacity: 1;
   168→  transform: translateY(0);
   169→}
   170→
   171→/* Stagger children */
   172→.bento-grid .reveal:nth-child(2) {
   173→  transition-delay: 0.1s;
   174→}
   175→
   176→.bento-grid .reveal:nth-child(3) {
   177→  transition-delay: 0.2s;
   178→}
   179→
   180→.bento-grid .reveal:nth-child(4) {
   181→  transition-delay: 0.3s;
   182→}
   183→
   184→/* ==========================================================================
   185→   Buttons
   186→   ========================================================================== */
   187→.btn {
   188→  display: inline-flex;
   189→  align-items: center;
   190→  justify-content: center;
   191→  padding: 0.65rem 1.75rem;
   192→  font-weight: 700;
   193→  text-transform: uppercase;
   194→  letter-spacing: var(--ls-wide);
   195→  border: var(--border-width) solid var(--clr-black);
   196→  transition: var(--transition);
   197→  font-size: var(--fs-sm);
   198→  font-family: var(--font-primary);
   199→  cursor: pointer;
   200→  outline-offset: 2px;
   201→}
   202→
   203→.btn:focus-visible {
   204→  outline: var(--focus-outline);
   205→}
   206→
   207→.btn-primary {
   208→  background-color: var(--clr-yellow);
   209→  color: var(--clr-black);
   210→  box-shadow: var(--shadow-solid);
   211→}
   212→
   213→.btn-primary:hover {
   214→  box-shadow: var(--shadow-solid-hover);
   215→  transform: translate(3px, 3px);
   216→  background-color: var(--clr-mint);
   217→}
   218→
   219→.btn-primary:active {
   220→  transform: translate(4px, 4px);
   221→  box-shadow: none;
   222→}
   223→
   224→.btn-outline {
   225→  background-color: var(--clr-white);
   226→  color: var(--clr-black);
   227→  box-shadow: var(--shadow-solid);
   228→}
   229→
   230→.btn-outline:hover {
   231→  box-shadow: var(--shadow-solid-hover);
   232→  transform: translate(3px, 3px);
   233→  background-color: var(--clr-yellow);
   234→}
   235→
   236→.btn-outline:active {
   237→  transform: translate(4px, 4px);
   238→  box-shadow: none;
   239→}
   240→
   241→.btn-lg {
   242→  font-size: var(--fs-md);
   243→  padding: 0.9rem 2.25rem;
   244→}
   245→
   246→/* ==========================================================================
   247→   Navbar
   248→   ========================================================================== */
   249→.navbar {
   250→  position: fixed;
   251→  top: 0;
   252→  left: 0;
   253→  width: 100%;
   254→  background-color: rgba(250, 250, 250, 0.92);
   255→  backdrop-filter: blur(12px);
   256→  -webkit-backdrop-filter: blur(12px);
   257→  border-bottom: var(--border-width) solid var(--clr-black);
   258→  z-index: 1000;
   259→  transition: var(--transition);
   260→}
   261→
   262→.navbar.scrolled {
   263→  padding: 0;
   264→}
   265→
   266→.nav-container {
   267→  display: flex;
   268→  justify-content: space-between;
   269→  align-items: center;
   270→  height: 80px;
   271→  padding: 0 var(--space-lg);
   272→}
   273→
   274→.logo {
   275→  display: flex;
   276→  align-items: center;
   277→  gap: 0.75rem;
   278→}
   279→
   280→.logo-img {
   281→  height: 52px;
   282→  width: auto;
   283→}
   284→
   285→.logo-text {
   286→  font-size: var(--fs-xl);
   287→  font-weight: 800;
   288→  letter-spacing: var(--ls-wider);
   289→}
   290→
   291→.nav-links {
   292→  display: flex;
   293→  align-items: center;
   294→  gap: 2.5rem;
   295→}
   296→
   297→.nav-link {
   298→  font-weight: 600;
   299→  font-size: var(--fs-sm);
   300→  text-transform: uppercase;
   301→  letter-spacing: var(--ls-wide);
   302→  position: relative;
   303→  padding: 0.5rem 0;
   304→  color: var(--clr-text);
   305→  outline-offset: 2px;
   306→}
   307→
   308→.nav-link:focus-visible {
   309→  outline: var(--focus-outline);
   310→}
   311→
   312→.nav-link::after {
   313→  content: '';
   314→  position: absolute;
   315→  bottom: 0;
   316→  left: 0;
   317→  width: 0%;
   318→  height: 2.5px;
   319→  background-color: var(--clr-yellow);
   320→  transition: var(--transition);
   321→}
   322→
   323→.nav-link:hover::after {
   324→  width: 100%;
   325→}
   326→
   327→.nav-btn {
   328→  background-color: var(--clr-yellow);
   329→  padding: 0.55rem 1.5rem;
   330→  border: var(--border-width) solid var(--clr-black);
   331→  font-weight: 700;
   332→  box-shadow: var(--shadow-md);
   333→  transition: var(--transition);
   334→  text-transform: uppercase;
   335→  font-size: var(--fs-sm);
   336→  letter-spacing: var(--ls-wide);
   337→  cursor: pointer;
   338→  outline-offset: 2px;
   339→}
   340→
   341→.nav-btn:focus-visible {
   342→  outline: var(--focus-outline);
   343→}
   344→
   345→.nav-btn:hover {
   346→  box-shadow: var(--shadow-sm);
   347→  transform: translate(1px, 1px);
   348→  background-color: var(--clr-mint);
   349→}
   350→
   351→.nav-btn:active {
   352→  transform: translate(2px, 2px);
   353→  box-shadow: none;
   354→}
   355→
   356→.mobile-menu-btn {
   357→  display: none;
   358→  background: none;
   359→  border: none;
   360→  flex-direction: column;
   361→  gap: 6px;
   362→  cursor: pointer;
   363→  padding: 8px;
   364→  outline-offset: 2px;
   365→}
   366→
   367→.mobile-menu-btn:focus-visible {
   368→  outline: var(--focus-outline);
   369→}
   370→
   371→.mobile-menu-btn span {
   372→  display: block;
   373→  width: 28px;
   374→  height: 2.5px;
   375→  background-color: var(--clr-black);
   376→  transition: var(--transition);
