   379→
   380→/* ==========================================================================
   381→   Hero Section
   382→   ========================================================================== */
   383→.hero {
   384→  min-height: 100vh;
   385→  display: flex;
   386→  align-items: center;
   387→  padding-top: 80px;
   388→  position: relative;
   389→  overflow: hidden;
   390→}
   391→
   392→.hero-container {
   393→  display: flex;
   394→  justify-content: center;
   395→  position: relative;
   396→  z-index: 1;
   397→}
   398→
   399→.hero-content {
   400→  max-width: 680px;
   401→}
   402→
   403→.hero-title {
   404→  font-size: var(--fs-7xl);
   405→  font-weight: 900;
   406→  line-height: var(--lh-tight);
   407→  margin-bottom: var(--space-lg);
   408→  letter-spacing: var(--ls-tight);
