   430→  text-align: center;
   431→  margin-bottom: var(--space-3xl);
   432→}
   433→
   434→.section-title {
   435→  font-size: var(--fs-5xl);
   436→  font-weight: 900;
   437→  margin-bottom: var(--space-lg);
   438→  display: inline-block;
   439→  position: relative;
   440→  letter-spacing: var(--ls-tight);
   441→}
   442→
   443→.section-title::after {
   444→  content: '';
   445→  position: absolute;
   446→  bottom: 6px;
   447→  left: -6px;
   448→  right: -6px;
   449→  height: 35%;
   450→  background-color: var(--clr-mint);
   451→  z-index: -1;
   452→  opacity: 0.5;
