   462→
   463→/* ==========================================================================
   464→   Bento Grid — Services
   465→   ========================================================================== */
   466→.bento-grid {
   467→  display: grid;
   468→  grid-template-columns: repeat(2, 1fr);
   469→  gap: var(--space-lg);
   470→}
   471→
   472→.bento-card {
   473→  background-color: var(--clr-white);
   474→  border: var(--border-width) solid var(--clr-black);
   475→  padding: var(--space-2xl);
   476→  display: flex;
   477→  flex-direction: column;
   478→  box-shadow: var(--shadow-solid);
   479→  transition: var(--transition);
   480→  position: relative;
   481→  overflow: hidden;
   482→}
   483→
   484→.bento-card:hover {
   485→  transform: translateY(-4px);
   486→  box-shadow: var(--shadow-xl);
   487→}
   488→
   489→.bento-card:focus-within {
   490→  outline: var(--focus-outline);
   491→  outline-offset: -4px;
   492→}
   493→
   494→.bento-card.bg-yellow {
   495→  background-color: var(--clr-yellow);
   496→}
   497→
   498→.bento-card.bg-mint {
   499→  background-color: var(--clr-mint);
   500→}
   501→
   502→.bento-icon {
   503→  font-size: var(--fs-3xl);
   504→  margin-bottom: var(--space-lg);
   505→  color: var(--clr-black);
   506→}
   507→
   508→.bento-card h3 {
   509→  font-size: var(--fs-2xl);
   510→  font-weight: 800;
   511→  margin-bottom: var(--space-md);
   512→  line-height: var(--lh-tight);
