   514→
   515→.bento-card p {
   516→  font-size: var(--fs-base);
   517→  line-height: var(--lh-normal);
   518→  margin-bottom: 0;
   519→  flex-grow: 1;
   520→  color: rgba(26, 26, 26, 0.8);
   521→}
   522→
   523→.bento-card.bg-yellow p,
   524→.bento-card.bg-mint p {
   525→  color: rgba(26, 26, 26, 0.85);
   526→}
   527→
   528→/* ==========================================================================
   529→   About Section
   530→   ========================================================================== */
   531→.about-container {
   532→  display: grid;
   533→  grid-template-columns: 1fr 1fr;
   534→  gap: var(--space-3xl);
   535→  align-items: center;
   536→}
   537→
   538→.about-desc {
   539→  font-size: var(--fs-md);
   540→  margin-bottom: var(--space-lg);
   541→  color: var(--clr-text-muted);
   542→  line-height: var(--lh-relaxed);
   543→}
   544→
   545→.about-list {
   546→  margin-bottom: var(--space-lg);
   547→}
   548→
   549→.about-list li {
