   691→
   692→.footer-tagline {
   693→  margin: var(--space-md) auto 0;
   694→  font-size: var(--fs-base);
   695→  color: var(--clr-grey);
   696→}
   697→
   698→.footer-bottom {
   699→  display: flex;
   700→  justify-content: center;
